(1795845, 244155, 43565, '<td valign="top">Is the music really reflecting off the keys?  I think a tighter crop would have been better, focusing on the keys with the clearest reflection.</td>', 'Is the music really reflecting off the keys?  I think a tighter crop would have been better, focusing on the keys with the clearest reflection.', '2005-10-19 15:31:26.000000', NULL, 1),
(1795847, 244892, 43774, '<td valign="top">A shadow is not a reflection, sorry.</td>', 'A shadow is not a reflection, sorry.', '2005-10-19 15:31:35.000000', NULL, 1),
(1795849, 243836, 43774, '<td valign="top">I don''t know what I am looking and and I don''t see reflections (I think I see shadows)</td>', 'I don''t know what I am looking and and I don''t see reflections (I think I see shadows)', '2005-10-19 15:32:17.000000', NULL, 1),
(1795850, 244782, 44061, '<td valign="top">Awesome picture.  My favorite!</td>', 'Awesome picture.  My favorite!', '2005-10-19 15:32:20.000000', NULL, 1),
