(1797934, 245888, 15407, '<td valign="top">The white lines of oversharpening distracted somewhat yet its sure a fine photo!</td>', 'The white lines of oversharpening distracted somewhat yet its sure a fine photo!', '2005-10-20 06:28:03.000000', NULL, 1),
(1797935, 243817, 15407, '<td valign="top">Found in a reflection!</td>', 'Found in a reflection!', '2005-10-20 06:28:50.000000', NULL, 1),
