(1799277, 246228, 29906, '<td valign="top">You know, a friend of mine suggested that I do exactly this for this challenge, and I didn''t, but even if I did, I wouldn''t have made an excellent shot like this.. Very nicely done, 10</td>', 'You know, a friend of mine suggested that I do exactly this for this challenge, and I didn''t, but even if I did, I wouldn''t have made an excellent shot like this.. Very nicely done, 10', '2005-10-20 19:40:04.000000', NULL, 1),
(1799282, 244631, 29906, '<td valign="top">Haha, I love Corona''s .. Good shot too ..</td>', 'Haha, I love Corona''s .. Good shot too ..', '2005-10-20 19:41:27.000000', NULL, 1),
(1799285, 246442, 29906, '<td valign="top">That is a masterpiece, 10</td>', 'That is a masterpiece, 10', '2005-10-20 19:41:57.000000', NULL, 1),
