(1799420, 244521, 30817, '<td valign="top">Striking image!  Well framed and exposed.</td>', 'Striking image!  Well framed and exposed.', '2005-10-20 20:46:18.000000', NULL, 1),
(1799423, 245922, 42714, '<td valign="top">Michaelangelo gone digital.  Great job using inference instead of being as literal in interpretation.  Though I think this could''ve benefited by zooming out a bit and perhaps capturing more of what''s happening...would make it seem more 3D than flat.</td>', 'Michaelangelo gone digital.  Great job using inference instead of being as literal in interpretation.  Though I think this could''ve benefited by zooming out a bit and perhaps capturing more of what''s happening...would make it seem more 3D than flat.', '2005-10-20 20:47:05.000000', NULL, 1),
(1799424, 244222, 44995, '<td valign="top">this is a cool shot but would be better if you couldn''t see the camera</td>', 'this is a cool shot but would be better if you couldn''t see the camera', '2005-10-20 20:47:15.000000', NULL, 1),
(1799431, 245408, 42714, '<td valign="top">Great industrial piece, a shame about those wires, but I know you can''t help that.  Would be interesting to see this compltely at night too.</td>', 'Great industrial piece, a shame about those wires, but I know you can''t help that.  Would be interesting to see this compltely at night too.', '2005-10-20 20:48:42.000000', NULL, 1),
