(1799503, 246192, 35804, '<td valign="top">Fantastic light and abstract...love the crisp clean colors...very nice.</td>', 'Fantastic light and abstract...love the crisp clean colors...very nice.', '2005-10-20 21:19:45.000000', NULL, 1),
(1799531, 244782, 35739, '<td valign="top">Excellent.  Nice colors. Top 10 I''m sure.</td>', 'Excellent.  Nice colors. Top 10 I''m sure.', '2005-10-20 21:39:19.000000', NULL, 1),
(1799536, 244395, 35739, '<td valign="top">Nice blur.  Well done! If the place had traveled alittle more. -8</td>', 'Nice blur.  Well done! If the place had traveled alittle more. -8', '2005-10-20 21:41:01.000000', NULL, 1),
