(1802500, 245844, 42574, '<td valign="top">Nice focus and beautiful colors. Well done.</td>', 'Nice focus and beautiful colors. Well done.', '2005-10-22 00:06:15.000000', NULL, 1),
(1802507, 246256, 39057, '<td valign="top">many reflections...pretty good...</td>', 'many reflections...pretty good...', '2005-10-22 00:14:25.000000', NULL, 1),
